def minCost(n: int, cost: List[List[int]]) -> int:
    # 縮減範圍：我們只需要處理前 n // 2 座房子
    # 因為每一對 (i, n-1-i) 的選擇是相關的
    half = n // 2

    # dp[c1][c2] 表示當考慮到第 i 對房子時，
    # 左邊房子用顏色 c1，右邊房子用顏色 c2 的最小成本。
    # 因為題目規定對稱位置顏色不同，所以 c1 != c2 永遠成立。
    # 初始化：處理第一對房子 (0, n-1)
    dp = [[float('inf')] * 3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            if i != j:
                dp[i][j] = cost[0][i] + cost[n-1][j]

    # 從第二對房子開始處理到中間
    # 如果 n=4, half=2, 我們處理 index 1 和 index (4-1-1)=2
    for i in range(1, half):
        new_dp = [[float('inf')] * 3 for _ in range(3)]
        j = n - 1 - i
        for curr_i in range(3):
            for curr_j in range(3):
                if curr_i == curr_j: continue # 對稱位置不能相同

                # 轉移：prev_i 不能等於 curr_i，且 prev_j 不能等於 curr_j
                # 同時要考慮當 i 和 j 相鄰時（即中間兩座），curr_i 不能等於 prev_j 且 curr_j 不能等於 prev_i
                # 但根據題目「相鄰不能相同」，在我們的結構中：
                # 左邊的房子與前一個左邊房子是相鄰，右邊的房子與後一個右邊房子是相鄰。
                for prev_i in range(3):
                    for prev_j in range(3):
                        if prev_i != curr_i and prev_j != curr_j:
                            # 額外條件：如果中間兩座房子相鄰 (i == j-1)
                            # 此時 curr_i 不能等於 prev_j，curr_j 不能等於 prev_i
                            if i == j - 1:
                                if curr_i == prev_j or curr_j == prev_i:
                                    continue

                            new_dp[curr_i][curr_j] = min(new_dp[curr_i][curr_j], dp[prev_i][prev_j] + cost[i][curr_i] + cost[j][curr_j])
        dp = new_dp

    ans = float('inf')
    for i in range(3):
        for j in range(3):
            ans = min(ans, dp[i][j])
    return int(ans)
